class LRUCacheTTL:
    def __init__(self, max_items: int, ttl_seconds: int):
        self.max_items = max_items
        self.ttl_seconds = ttl_seconds
        self._lock = threading.Lock()
        self._data: OrderedDict[str, Tuple[int, Any]] = OrderedDict()

    def get(self, key: str) -> Optional[Any]:
        now = int(time.time())
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            ts, val = item
            if now - ts > self.ttl_seconds:
                try:
                    del self._data[key]
                except Exception:
                    pass
                return None
            self._data.move_to_end(key, last=True)
            return val

    def set(self, key: str, value: Any) -> None:
        now = int(time.time())
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key, last=True)
            self._data[key] = (now, value)
            while len(self._data) > self.max_items:
                self._data.popitem(last=False)

    def cleanup(self) -> None:
        now = int(time.time())
        with self._lock:
            keys = list(self._data.keys())
            for k in keys:
                ts, _ = self._data.get(k, (0, None))
                if now - ts > self.ttl_seconds:
                    try:
                        del self._data[k]
                    except Exception:
                        pass

class SlidingWindowRateLimiter:
    def __init__(self, max_per_minute: int):
        self.max_per_minute = max_per_minute
        self._lock = threading.Lock()
        self._buckets: Dict[str, deque] = defaultdict(deque)

    def allow(self, key: str) -> bool:
        now = time.time()
        with self._lock:
            q = self._buckets[key]
            while q and (now - q[0]) > 60.0:
                q.popleft()
            if len(q) >= self.max_per_minute:
                return False
            q.append(now)
            return True

class CircuitBreaker:
    def __init__(self, fail_threshold: int, cooldown_seconds: int):
        self.fail_threshold = fail_threshold
        self.cooldown_seconds = cooldown_seconds
        self._lock = threading.Lock()
        self._fails: Dict[str, int] = defaultdict(int)
        self._open_until: Dict[str, float] = defaultdict(float)

    def can_call(self, name: str) -> bool:
        now = time.time()
        with self._lock:
            until = self._open_until.get(name, 0.0)
            if until and now < until:
                return False
            return True

    def record_success(self, name: str) -> None:
        with self._lock:
            self._fails[name] = 0
            self._open_until[name] = 0.0

    def record_failure(self, name: str) -> None:
        now = time.time()
        with self._lock:
            self._fails[name] += 1
            if self._fails[name] >= self.fail_threshold:
                self._open_until[name] = now + float(self.cooldown_seconds)

class InFlightDeduper:
    def __init__(self):
        self._lock = threading.Lock()
        self._events: Dict[str, threading.Event] = {}
        self._results: Dict[str, Any] = {}

    def begin(self, key: str) -> Tuple[bool, Optional[Any], Optional[threading.Event]]:
        with self._lock:
            if key in self._events:
                ev = self._events[key]
                return False, None, ev
            ev = threading.Event()
            self._events[key] = ev
            return True, None, ev

    def set_result(self, key: str, result: Any) -> None:
        with self._lock:
            self._results[key] = result
            ev = self._events.get(key)
            if ev is not None:
                ev.set()

    def wait_result(self, key: str, ev: threading.Event, timeout: float) -> Optional[Any]:
        ev.wait(timeout=timeout)
        with self._lock:
            return self._results.get(key)

    def end(self, key: str) -> None:
        with self._lock:
            self._events.pop(key, None)
            self._results.pop(key, None)

