        now = time.time()
        with self._lock:
            self._counts[nq] += 1
            self._last_ts[nq] = now

    def suggestions(self, prefix: str, limit: int = 10) -> List[str]:
        p = (prefix or "").strip().lower()
        if p == "":
            return []
        with self._lock:
            candidates = []
            for q, c in self._counts.items():
                if q.lower().startswith(p):
                    candidates.append((q, c, self._last_ts.get(q, 0.0)))
            candidates.sort(key=lambda x: (x[1], x[2]), reverse=True)
            return [x[0] for x in candidates[:limit]]

