    def _extract_main_text(self, html: str) -> str:
        soup = BeautifulSoup(html, "html.parser")
        for tag in soup(["script", "style", "noscript", "svg", "canvas", "iframe"]):
            try:
                tag.decompose()
            except Exception:
                pass
        for tag_name in ["header", "footer", "nav", "aside", "form"]:
            for tag in soup.find_all(tag_name):
                try:
                    tag.decompose()
                except Exception:
                    pass
        body = soup.body if soup.body is not None else soup
        candidates = []
        for container in body.find_all(["article", "main", "section", "div"], recursive=True):
            text = container.get_text(separator=" ", strip=True)
            if not text:
                continue
            if len(text) < 400:
                continue
            density = len(text) / max(1, len(container.find_all(True)))
            candidates.append((len(text), density, container))
        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
            chosen = candidates[0][2]
        else:
            chosen = body
        for tag in chosen.find_all(True):
            if tag.name in ["a", "span", "p", "li", "h1", "h2", "h3", "h4", "h5", "h6", "blockquote", "pre", "code"]:
                continue
            if tag.get("aria-hidden") == "true":
                try:
                    tag.decompose()
                except Exception:
                    pass
        txt = chosen.get_text(separator="\n", strip=True)
        txt = re.sub(r"\n{3,}", "\n\n", txt)
        txt = re.sub(r"[ \t]{2,}", " ", txt)
        return txt.strip()

