    def _chunk_text(self, text: str, chunk_size: int, overlap: int) -> List[str]:
        if not text:
            return []
        t = text.strip()
        if len(t) <= chunk_size:
            return [t]
        chunks = []
        i = 0
        while i < len(t):
            j = min(len(t), i + chunk_size)
            chunk = t[i:j]
            chunks.append(chunk)
            if j == len(t):
                break
            i = max(0, j - overlap)
        return chunks

