        for u, t in sources:
            compiled.append(f"SOURCE_URL: {u}\nCONTENT:\n{t}\n")
        compiled_text = "\n\n".join(compiled)
        chunks = self._chunk_text(compiled_text, chunk_size=6000, overlap=600)
        context = "\n\n".join(chunks[:4])
        system = "Generate a comprehensive, precise answer to the user's query using only the provided sources. Include a numbered Sources list with the SOURCE_URL values you used. Output plain text."
        user = f"QUERY:\n{query}\n\nSOURCES:\n{context}"
        payload: Dict[str, Any] = {
            "model": self.perplexity_synthesis_model,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": user}
            ],
            "temperature": 0.7,
            "top_p": 0.9,
            "max_tokens": 1500,
            "search_mode": "web"
        }
        async with aiohttp.ClientSession(headers=headers) as session:
            try:
                backoffs = [1.0, 2.0, 4.0]
                for attempt in range(4):
                    status, data, raw = await self._aiohttp_post_json(session, url, headers=headers, payload=payload, timeout_sec=self.search_timeout_sec)
                    if status == 429 and attempt < 3:
                        await asyncio.sleep(backoffs[attempt])
                        continue
                    if status != 200 or not isinstance(data, dict):
                        break
                    choices = data.get("choices") or []
                    content = ""
                    if choices and isinstance(choices, list):
                        msg = (choices[0].get("message") or {}) if isinstance(choices[0], dict) else {}
                        content = msg.get("content") or ""
                    if isinstance(content, str) and content.strip():
                        self.circuit.record_success(name)
                        dur = _ms() - started
                        _log("INFO", "perplexity_synthesis", f"ok duration_ms={dur}")
                        return content.strip()
                    break
                self.circuit.record_failure(name)
                dur = _ms() - started
                _log("ERROR", "perplexity_synthesis", f"fail status={status} duration_ms={dur}")
                return ""
            except Exception as e:
                self.circuit.record_failure(name)
                dur = _ms() - started
                _log("ERROR", "perplexity_synthesis", f"fail duration_ms={dur} error={str(e)}")
                return ""

    async def aggregate(self, query: str, want: int) -> Tuple[List[Dict[str, Any]], Dict[str, bool]]:
        started = _ms()
        tasks = []
        tasks.append(self.serpapi_search(query, want=want))
        tasks.append(self.exa_search(query, want=want))
        tasks.append(self.perplexity_search(query, want=want))
        results = await asyncio.gather(*tasks, return_exceptions=True)
        serp = results[0] if isinstance(results[0], list) else []
        exa = results[1] if isinstance(results[1], list) else []
        ppl = results[2] if isinstance(results[2], list) else []
        api_status = {
            "serpapi": bool(serp),
            "exa": bool(exa),
            "perplexity": bool(ppl)
        }
        merged = []
        for r in serp:
            merged.append(r)
        for r in exa:
            merged.append(r)
        for r in ppl:
            merged.append(r)
        seen = set()
        deduped: List[Dict[str, Any]] = []
        for r in merged:
            u = r.get("url", "")
            nu = _normalize_url(u)
            if not nu or nu in seen:
                continue
            seen.add(nu)
            r["url"] = nu
            r["domain"] = r.get("domain") or _extract_domain(nu)
            deduped.append(r)
        for idx, r in enumerate(deduped):
            src = r.get("source", "")
            pos = r.get("position", 0)
            try:
                posn = int(pos) if pos is not None else 0
            except Exception:
                posn = 0
            base = 0.0
            if src == "serpapi":
                base = 0.85
            elif src == "exa":
                base = 0.8
            elif src == "perplexity":
                base = 0.75
            rel = base * (1.0 / max(1.0, float(posn)))
            r["relevance_score"] = float(min(1.0, max(0.0, rel)))
        deduped.sort(key=lambda x: x.get("relevance_score", 0.0), reverse=True)
        if want > 0:
            deduped = deduped[:want]
        dur = _ms() - started
        _log("INFO", "aggregate", f"ok merged={len(merged)} deduped={len(deduped)} duration_ms={dur}")
        return deduped, api_status

