app.config["JSON_AS_ASCII"] = False
CORS(app, resources={r"/api/*": {"origins": "*"}})

MAX_REQUESTS_PER_MINUTE = _env_int("MAX_REQUESTS_PER_MINUTE", default=10, min_value=1, max_value=120)
CACHE_TTL_HOURS = _env_int("CACHE_TTL_HOURS", default=24, min_value=1, max_value=168)
CACHE_MAX_ITEMS = _env_int("CACHE_MAX_ITEMS", default=1000, min_value=10, max_value=10000)
DEDUPER_WAIT_SEC = float(_env_int("DEDUPER_WAIT_SEC", default=60, min_value=5, max_value=300))

rate_limiter = SlidingWindowRateLimiter(max_per_minute=MAX_REQUESTS_PER_MINUTE)
cache = LRUCacheTTL(max_items=CACHE_MAX_ITEMS, ttl_seconds=CACHE_TTL_HOURS * 3600)
deduper = InFlightDeduper()
history = QueryHistory()
aggregator = SearchAggregator()

def _client_ip() -> str:
    xf = request.headers.get("X-Forwarded-For", "")
    if xf:
        return xf.split(",")[0].strip()
    return request.remote_addr or "unknown"

def _gzip_if_accepted(resp: Response) -> Response:
    ae = request.headers.get("Accept-Encoding", "")
    if "gzip" not in ae.lower():
        return resp
    data = resp.get_data()
    if data is None or len(data) < 1024:
        return resp
    gz = gzip.compress(data, compresslevel=6)
    resp.set_data(gz)
    resp.headers["Content-Encoding"] = "gzip"
    resp.headers["Content-Length"] = str(len(gz))
    return resp

@app.before_request
def _before() -> None:
    request._start_ms = _ms()
    request._rid = str(uuid.uuid4())

@app.after_request
def _after(resp: Response) -> Response:
    resp.headers["X-Request-Id"] = getattr(request, "_rid", "")
    start = getattr(request, "_start_ms", _ms())
    resp.headers["X-Response-Time-ms"] = str(max(0, _ms() - start))
    resp.headers["Content-Type"] = resp.headers.get("Content-Type", "application/json; charset=utf-8")
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "DENY"
    resp.headers["X-XSS-Protection"] = "1; mode=block"
    resp.headers["Strict-Transport-Security"] = "max-age=31536000"
    try:
        resp = _gzip_if_accepted(resp)
    except Exception:
        pass
    return resp

@app.route("/api/health", methods=["GET"])
def health_check() -> Response:
    ok = True
    missing = []
    if not aggregator.serpapi_key:
        missing.append("SERPAPI_KEY")
    if not aggregator.exa_api_key:
        missing.append("EXA_API_KEY")
    if not aggregator.perplexity_api_key:
        missing.append("PERPLEXITY_API_KEY")
    if missing:
        ok = False
    status = 200 if ok else 503
    data = {"status": "healthy" if ok else "degraded", "timestamp": _now_iso(), "version": "1.0.0", "missing": missing}
    return _json_response(data, status=status)

@app.route("/api/suggestions", methods=["GET"])
def suggestions() -> Response:
    q = request.args.get("q", "")
    s = history.suggestions(q, limit=10)
    return _json_response({"suggestions": s, "timestamp": _now_iso()}, status=200)

def _search_work(query: str, limit: int, offset: int) -> Dict[str, Any]:
    async def run() -> Dict[str, Any]:
        results_all, api_status = await aggregator.aggregate(query, want=max(100, limit + offset))
        total_results = len(results_all)
        slice_results = results_all[offset:offset + limit] if offset < total_results else []
        top_urls = [r["url"] for r in results_all[:aggregator.fetch_top_k] if r.get("url")]
        extracted = await aggregator.fetch_and_extract(top_urls) if aggregator.fetch_top_k > 0 else {}
        sources = []
        for u in top_urls:
            t = extracted.get(_normalize_url(u))
            if t:
                sources.append((u, t))
        synthesis = ""
        if sources:
            synthesis = await aggregator.perplexity_synthesize(query, sources=sources)
        if not synthesis:
            snippets = []
            for r in results_all[:3]:
                sn = (r.get("snippet") or "").strip()
                if sn:
                    snippets.append(sn)
            synthesis = " ".join(snippets).strip()
        return {
            "results": slice_results,
            "synthesis": synthesis,
            "total_results": total_results,
            "query": query,
            "timestamp": _now_iso(),
            "api_status": api_status
        }
    return asyncio.run(run())

@app.route("/api/search", methods=["POST"])
def search() -> Response:
    ip = _client_ip()
    if not rate_limiter.allow(ip):
        _log("WARNING", "rate_limit", f"blocked ip={ip}")
        return _json_response({"error": "rate_limit_exceeded", "message": "Too many requests. Try again later.", "timestamp": _now_iso()}, status=429)
    try:
        payload = request.get_json(force=True, silent=False) or {}
    except Exception:
        return _json_response({"error": "invalid_json", "message": "Request body must be valid JSON.", "timestamp": _now_iso()}, status=400)
    query = payload.get("query", "")
    limit, offset = _validate_limit_offset(payload.get("limit", 100), payload.get("offset", 0))
    try:
        _validate_query(query)
    except Exception as e:
        return _json_response({"error": "invalid_query", "message": str(e), "timestamp": _now_iso()}, status=400)
    query_n = _normalize_query(query)
    cache_key = f"search:{_hash_key(query_n)}:{limit}:{offset}"
    cached = cache.get(cache_key)
    if cached is not None:
        _log("INFO", "cache", f"hit ip={ip} query={query_n}")
        return _json_response(cached, status=200)
    started_here, _, ev = deduper.begin(cache_key)
    if not started_here and ev is not None:
        _log("INFO", "dedupe", f"wait ip={ip} query={query_n}")
        res = deduper.wait_result(cache_key, ev, timeout=DEDUPER_WAIT_SEC)
        if res is not None:
            return _json_response(res, status=200)
        deduper.end(cache_key)
    rid = getattr(request, "_rid", "")
    t0 = _ms()
    _log("INFO", "request", f"rid={rid} ip={ip} query={query_n} limit={limit} offset={offset}")
    history.record(query_n)
    try:
        result = _search_work(query_n, limit=limit, offset=offset)
        cache.set(cache_key, result)
        deduper.set_result(cache_key, result)
        t1 = _ms()
        _log("INFO", "response", f"rid={rid} ip={ip} query={query_n} duration_ms={t1 - t0} results={len(result.get('results', []))}")
        return _json_response(result, status=200)
    except Exception as e:
        err = {"error": "search_failed", "message": str(e), "query": query_n, "timestamp": _now_iso()}
        deduper.set_result(cache_key, err)
        _log("ERROR", "search", f"rid={rid} ip={ip} query={query_n} error={str(e)}")
        return _json_response(err, status=500)
    finally:
        deduper.end(cache_key)

if __name__ == "__main__":
    host = _env_str("HOST", default="0.0.0.0", required=False)
    port = _env_int("PORT", default=5000, min_value=1, max_value=65535)
